def verify(x):
 cat,(name,url)=x
 try:
  r=requests.get(url,timeout=22,headers={'User-Agent':'NewsJockey/0.1 (local personal RSS reader)'})
  p=feedparser.parse(r.content)
  entries=p.entries
  return dict(category=cat,name=name,feed_url=url,resolved_url=r.url,status=r.status_code,entries=len(entries),title=p.feed.get('title',''),latest=entries[0].get('published','') if entries else '',error=str(p.get('bozo_exception',''))[:140])
 except Exception as e:return dict(category=cat,name=name,feed_url=url,entries=0,error=str(e)[:140])
with concurrent.futures.ThreadPoolExecutor(max_workers=12) as pool:
 results=list(pool.map(verify,[(cat,x) for cat,rows in candidates.items() for x in rows]))
open('tools/candidate_results.json','w').write(json.dumps(results,indent=2))
for r in results: print(r['category'],r['name'],r.get('status'),r['entries'],r.get('latest'),r.get('error'))
